    case MOBY_STATE_INITIALIZE:
        moby->update_dist = 0xFF;
        moby->state = 1;
        break;
    case MOBY_STATE_UPDATE:
        current_scene_state = scene_state;
        if (current_scene_state != 2)
            return;
        S = D_L07_0016C960_c;
